const AlchemystAI = require('@alchemystai/sdk');

async function main() {
  const apiKey = process.env.ALCHEMYST_AI_API_KEY;
  const runId = process.env.ZEALT_RUN_ID || 'test';

  const client = new AlchemystAI({ apiKey });

  // Monkey patch client.v1.context.memory.search
  client.v1.context.memory.search = function(body, options) {
    return this._client.post('/api/v1/context/memory/search', { body, ...options });
  };

  const userId = `user-${runId}`;
  const sessionA = `session_A-${runId}`;
  const sessionB = `session_B-${runId}`;

  console.log(`Using userId: ${userId}`);
  console.log(`Using sessionA: ${sessionA}`);
  console.log(`Using sessionB: ${sessionB}`);

  console.log('Adding memory under sessionA...');
  try {
    const addRes = await client.v1.context.memory.add({
      userId,
      user_id: userId,
      sessionId: sessionA,
      session_id: sessionA,
      contents: [
        { content: 'User is vegan and allergic to peanuts' }
      ]
    });
    console.log('Add response:', JSON.stringify(addRes, null, 2));
  } catch (err) {
    console.error('Add error:', err);
  }

  console.log('Searching memory under sessionB...');
  try {
    const searchRes = await client.v1.context.memory.search({
      userId,
      user_id: userId,
      sessionId: sessionB,
      session_id: sessionB,
      query: 'What are my allergies and dietary restrictions?'
    });
    console.log('Search response:', JSON.stringify(searchRes, null, 2));
  } catch (err) {
    console.error('Search error:', err);
  }
}

