async function testEndpoint(client, name, path, body) {
  console.log(`\n--- Testing ${name} (${path}) ---`);
  try {
    const res = await client._client.post(path, { body });
    console.log(`${name} SUCCESS:`, JSON.stringify(res, null, 2));
    return true;
  } catch (err) {
